-- Login Activity & Devices: run once in Supabase SQL Editor.
create table if not exists public.login_devices(session_id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,device_key_hash text not null,browser text not null default 'Unknown browser',os text not null default 'Unknown OS',device_type text not null default 'Computer',login_at timestamptz not null default now(),last_active timestamptz not null default now());
create index if not exists login_devices_user_idx on public.login_devices(user_id,last_active desc);
alter table public.login_devices enable row level security;
revoke all on public.login_devices from anon,authenticated;

create or replace function public.current_session_id() returns uuid language plpgsql stable security definer set search_path=pg_catalog,auth as $$declare value text;begin value:=auth.jwt()->>'session_id';if value is null or value='' then return null;end if;return value::uuid;exception when invalid_text_representation then return null;end$$;
create or replace function public.is_dashboard_admin() returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select exists(select 1 from public.profiles where id=auth.uid() and lower(role::text)='admin')$$;
create or replace function public.is_live_auth_session() returns boolean language sql stable security definer set search_path=pg_catalog,auth,public as $$select exists(select 1 from auth.sessions where id=public.current_session_id() and user_id=auth.uid())$$;

create or replace function public.register_login_device(p_device_key text,p_browser text,p_os text,p_device_type text) returns void language plpgsql security definer set search_path=pg_catalog,public,auth as $$declare sid uuid:=public.current_session_id();uid uuid:=auth.uid();begin if uid is null or sid is null or not public.is_live_auth_session() then raise exception 'Invalid session' using errcode='42501';end if;if not exists(select 1 from public.profiles where id=uid and lower(role::text) in('admin','staff'))then raise exception 'Account is not authorized' using errcode='42501';end if;insert into public.login_devices(session_id,user_id,device_key_hash,browser,os,device_type)values(sid,uid,md5(p_device_key),left(coalesce(p_browser,'Unknown browser'),80),left(coalesce(p_os,'Unknown OS'),80),left(coalesce(p_device_type,'Computer'),30))on conflict(session_id)do update set last_active=now(),browser=excluded.browser,os=excluded.os,device_type=excluded.device_type;end$$;

create or replace function public.list_login_devices() returns table(session_id uuid,account_email text,role text,browser text,os text,device_type text,login_at timestamptz,last_active timestamptz,is_current boolean) language sql security definer set search_path=pg_catalog,public,auth as $$select d.session_id,u.email::text,lower(p.role::text),d.browser,d.os,d.device_type,d.login_at,d.last_active,d.session_id=public.current_session_id() from public.login_devices d join auth.users u on u.id=d.user_id join public.profiles p on p.id=d.user_id where public.is_live_auth_session() and(d.user_id=auth.uid() or public.is_dashboard_admin())order by d.last_active desc$$;

create or replace function public.logout_login_device(p_session_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,auth as $$declare owner_id uuid;begin if not public.is_live_auth_session()then raise exception 'Invalid session' using errcode='42501';end if;select user_id into owner_id from public.login_devices where session_id=p_session_id;if owner_id is null or(owner_id<>auth.uid() and not public.is_dashboard_admin())then raise exception 'Not authorized' using errcode='42501';end if;delete from auth.sessions where id=p_session_id;delete from public.login_devices where session_id=p_session_id;end$$;

create or replace function public.logout_all_login_devices(p_email text) returns void language plpgsql security definer set search_path=pg_catalog,public,auth as $$declare target uuid;begin if not public.is_live_auth_session()or not public.is_dashboard_admin()then raise exception 'Admin only' using errcode='42501';end if;select id into target from auth.users where lower(email)=lower(p_email);if target is null then raise exception 'Account not found';end if;delete from auth.sessions where user_id=target;delete from public.login_devices where user_id=target;end$$;

revoke all on function public.current_session_id(),public.is_dashboard_admin(),public.is_live_auth_session(),public.register_login_device(text,text,text,text),public.list_login_devices(),public.logout_login_device(uuid),public.logout_all_login_devices(text) from public,anon;
grant execute on function public.register_login_device(text,text,text,text),public.list_login_devices(),public.logout_login_device(uuid),public.logout_all_login_devices(text) to authenticated;

-- Makes remote logout effective even from an old deployed frontend.
do $$declare r record;begin for r in select n.nspname s,c.relname t from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in('r','p')and c.relname<>'login_devices' loop execute format('alter table %I.%I enable row level security',r.s,r.t);execute format('drop policy if exists require_live_dashboard_session on %I.%I',r.s,r.t);execute format('create policy require_live_dashboard_session on %I.%I as restrictive for all to authenticated using(public.is_live_auth_session()) with check(public.is_live_auth_session())',r.s,r.t);end loop;end$$;
